CREATE TABLE sub (adsh text PRIMARY KEY, cik int, name text, form text, fy int, fp text, period int);
CREATE TABLE num (adsh text REFERENCES sub(adsh), tag text, version text, ddate int, qtrs int, uom text, coreg text, value numeric);

Question: For the company named 'AMAZON COM INC', return the value of tag 'Revenues' for form 10-K, qtrs=4, uom USD, with coreg null, ddate equal to the sub period.
